/* Nutrition/body journal is independent of training records and training drafts. */
const nutritionKey='nextstep.nutrition';
const mealTypes=[['breakfast','早餐'],['lunch','午餐'],['dinner','晚餐'],['snack','加餐']];
const bodyMethods=[['scale','普通秤'],['home-bia','家用体脂秤'],['professional','专业测量'],['manual','手填']];
const nClone=value=>JSON.parse(JSON.stringify(value));
const nObject=value=>value&&typeof value==='object'&&!Array.isArray(value);
const nFinite=(value,min,max)=>typeof value==='number'&&Number.isFinite(value)&&value>=min&&value<=max;
const nText=(value,max)=>typeof value==='string'&&value.length<=max;
const nIdentity=value=>typeof value==='string'&&/^[a-zA-Z0-9_.:-]{1,100}$/.test(value);
function nDate(date=new Date()){return [date.getFullYear(),String(date.getMonth()+1).padStart(2,'0'),String(date.getDate()).padStart(2,'0')].join('-')}
function nCalendarDate(date){return typeof date==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(date)&&nDate(new Date(date+'T12:00:00'))===date}
function nValidDate(date){return nCalendarDate(date)&&date<=nDate()}
function nShift(date,days){const value=new Date(date+'T12:00:00');value.setDate(value.getDate()+days);return nDate(value)}
function nId(){return globalThis.crypto?.randomUUID?.()||'n-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2)}
function emptyNutrition(){return {schemaVersion:1,revision:0,meals:[],dayStates:{},measurements:[],representativeByDate:{},energyPlans:[],customFoods:[],favoriteCombos:[],favoriteFoodIds:[],mealDraft:null}}
function nValidItem(item){return nObject(item)&&nIdentity(item.id)&&nIdentity(item.foodId)&&nText(item.name,60)&&['g','ml','个','块','份'].includes(item.unit)&&nFinite(item.quantity,0.01,['g','ml'].includes(item.unit)?10000:100)&&nObject(item.basis)&&nFinite(item.basis.amount,0.01,10000)&&item.basis.unit===item.unit&&(item.basis.energyKcal===null||nFinite(item.basis.energyKcal,0,20000))&&nObject(item.sourceSnapshot)&&nText(item.sourceSnapshot.type,60)&&nText(item.note||'',1000)}
function nValidPlan(plan){return nObject(plan)&&nIdentity(plan.id)&&nCalendarDate(plan.effectiveFrom)&&plan.method==='manual'&&nFinite(plan.targetKcal,1,20000)&&(plan.tdeeKcal===null||nFinite(plan.tdeeKcal,1,20000))&&['maintain','lose','gain'].includes(plan.goal)&&nFinite(plan.createdAt,1,Number.MAX_SAFE_INTEGER)}
function nValidMeasurement(item){return nObject(item)&&nIdentity(item.id)&&nValidDate(item.date)&&(item.localTime===null||/^([01]\d|2[0-3]):[0-5]\d$/.test(item.localTime))&&nFinite(item.weightKg,20,300)&&(item.bodyFatPercent===null||nFinite(item.bodyFatPercent,0.1,99.9))&&bodyMethods.some(([id])=>id===item.method)&&nText(item.device,60)&&nText(item.note,300)&&nFinite(item.createdAt,1,Number.MAX_SAFE_INTEGER)&&nFinite(item.updatedAt,1,Number.MAX_SAFE_INTEGER)}
function nValidMeal(meal){return nObject(meal)&&nIdentity(meal.id)&&nValidDate(meal.date)&&mealTypes.some(([id])=>id===meal.mealType)&&nText(meal.name,60)&&nText(meal.note,300)&&Array.isArray(meal.items)&&meal.items.length<=100&&meal.items.every(nValidItem)&&['items','manual'].includes(meal.energyMode)&&(meal.manualEnergyKcal===null||nFinite(meal.manualEnergyKcal,0,20000))&&(meal.energyMode!=='manual'||meal.manualEnergyKcal!==null)&&meal.items.length>0&&Number.isSafeInteger(meal.revision)&&meal.revision>0&&nFinite(meal.createdAt,1,Number.MAX_SAFE_INTEGER)&&nFinite(meal.updatedAt,1,Number.MAX_SAFE_INTEGER)}
function validateNutrition(data){
  if(!nObject(data)||data.schemaVersion!==1||!Number.isSafeInteger(data.revision)||data.revision<0)return false;
  if(!['meals','measurements','energyPlans','customFoods','favoriteCombos','favoriteFoodIds'].every(key=>Array.isArray(data[key])))return false;
  if(!data.meals.every(nValidMeal)||!data.measurements.every(nValidMeasurement)||!data.energyPlans.every(nValidPlan)||!data.customFoods.every(nValidItem))return false;
  if(!nObject(data.dayStates)||!nObject(data.representativeByDate))return false;
  if(!Object.entries(data.dayStates).every(([date,s])=>nValidDate(date)&&nObject(s)&&Number.isSafeInteger(s.revision)&&s.revision>=0&&(s.confirmedRevision===null||Number.isSafeInteger(s.confirmedRevision))&&(s.energyPlanSnapshot===null||nValidPlan(s.energyPlanSnapshot))&&(!s.skipped||Array.isArray(s.skipped)&&s.skipped.every(t=>mealTypes.some(([id])=>id===t)))))return false;
  if(!Object.entries(data.representativeByDate).every(([date,id])=>nValidDate(date)&&typeof id==='string'&&data.measurements.some(m=>m.id===id&&m.date===date)))return false;
  if(!data.favoriteCombos.every(c=>nObject(c)&&nIdentity(c.id)&&nText(c.name,60)&&Array.isArray(c.items)&&c.items.length>0&&c.items.length<=100&&c.items.every(nValidItem)))return false;
  if(!data.favoriteFoodIds.every(nIdentity))return false;
  if(data.mealDraft!==null&&(!nObject(data.mealDraft)||!nIdentity(data.mealDraft.id)||!nValidDate(data.mealDraft.date)||!mealTypes.some(([id])=>id===data.mealDraft.mealType)||!nText(data.mealDraft.name,60)||!nText(data.mealDraft.note,300)||!['items','manual'].includes(data.mealDraft.energyMode)||(data.mealDraft.manualEnergyKcal!==null&&!nFinite(data.mealDraft.manualEnergyKcal,0,20000))||!['picker','params'].includes(data.mealDraft.step)||!Array.isArray(data.mealDraft.items)||data.mealDraft.items.length>100||!data.mealDraft.items.every(nValidItem)))return false;
  for(const key of ['meals','measurements','energyPlans','customFoods','favoriteCombos'])if(new Set(data[key].map(x=>x.id)).size!==data[key].length)return false;
  return true;
}
let nutrition=emptyNutrition(),nutritionRaw=null,nutritionProblem='',nutritionConflict=false,nutritionQueue=Promise.resolve();
function loadNutrition(){
  nutritionProblem='';nutritionConflict=false;
  try{nutritionRaw=localStorage.getItem(nutritionKey);if(nutritionRaw===null){nutrition=emptyNutrition();return}const loaded=JSON.parse(nutritionRaw);if(!validateNutrition(loaded))throw Error('invalid');nutrition=loaded}
  catch{nutrition=emptyNutrition();nutritionProblem='饮食与身体数据无法安全读取，请先导出原始数据备份。未覆盖原数据。'}
}
loadNutrition();
function nutritionExport(){return nutritionProblem?{schemaVersion:1,readOnly:true,raw:nutritionRaw,error:nutritionProblem}:nClone(nutrition)}
function nError(message){const el=document.getElementById('nutrition-error');if(el)el.textContent=message;toast(message);return false}
function nWritable(){if(nutritionProblem)return nError(nutritionProblem);if(!globalThis.navigator?.locks?.request)return nError('当前浏览器不支持安全保存，请用新版浏览器或更新 Android System WebView。');if(nutritionConflict)return nError('其他窗口已更新数据，请先保留当前内容并重新载入。');return true}
function nCommit(update){
  const run=async()=>{
    if(!nWritable())return false;
    try{return await navigator.locks.request('nextstep-nutrition-write',()=>{
      if(localStorage.getItem(nutritionKey)!==nutritionRaw){nutritionConflict=true;return nError('其他窗口已更新数据；填写内容已保留，请导出当前草稿后重新载入。')}
      const next=nClone(nutrition);if(update(next)===false)return false;next.revision++;
      if(!validateNutrition(next))return nError('记录格式无效，请核对填写内容。');
      const raw=JSON.stringify(next);localStorage.setItem(nutritionKey,raw);nutrition=next;nutritionRaw=raw;return true;
    })}catch{return nError('保存失败，填写内容已保留，请重试或导出备份。')}
  };
  const result=nutritionQueue.then(run,run);nutritionQueue=result.then(()=>{});return result;
}
function nEffectivePlan(date,data=nutrition){return [...data.energyPlans].reverse().filter(p=>p.effectiveFrom<=date).sort((a,b)=>b.effectiveFrom.localeCompare(a.effectiveFrom)||b.createdAt-a.createdAt)[0]||null}
function nTouchDay(data,date){const old=data.dayStates[date];data.dayStates[date]={revision:(old?.revision||0)+1,confirmedRevision:null,confirmedAt:null,energyPlanSnapshot:old?old.energyPlanSnapshot:nClone(nEffectivePlan(date,data)),skipped:old?.skipped||[]}}
function nItemCalories(item){return item.basis.energyKcal===null?null:item.quantity/item.basis.amount*item.basis.energyKcal}
function nMealCalories(meal){if(meal.energyMode==='manual')return {known:meal.manualEnergyKcal,unknown:0};return meal.items.reduce((sum,item)=>{const kcal=nItemCalories(item);if(kcal===null)sum.unknown++;else sum.known+=kcal;return sum},{known:0,unknown:0})}
function nutritionDay(date,data=nutrition){
  const meals=data.meals.filter(m=>m.date===date),s=data.dayStates[date],plan=s?s.energyPlanSnapshot:nEffectivePlan(date,data);
  const sums=meals.reduce((n,m)=>{const c=nMealCalories(m);n.known+=c.known;n.unknown+=c.unknown;return n},{known:0,unknown:0});
  const complete=!!(meals.length&&s&&s.confirmedRevision!==null&&s.confirmedRevision===s.revision);
  return {date,meals,...sums,plan,complete,remaining:plan?plan.targetKcal-sums.known:null,deficit:complete&&!sums.unknown&&plan?.tdeeKcal!==null&&plan?.tdeeKcal!==undefined?plan.tdeeKcal-sums.known:null};
}
function nKcal(value){return value===null?'待填写热量':'约 '+Math.round(value).toLocaleString()+' kcal'}
function nDifference(value){return value===null?'尚未设置饮食目标':Math.abs(value)<0.5?'接近目标':value>0?'距目标约 '+Math.round(value)+' kcal':'比目标多约 '+Math.round(-value)+' kcal'}
function nGapText(day){if(!day.meals.length)return '暂无饮食记录';if(day.unknown)return '部分项目无热量，暂不计算缺口';if(!day.complete)return '待确认当天饮食已记全';if(!day.plan?.tdeeKcal)return '尚未填写全天维持消耗';return (day.deficit>=0?'估算缺口 ':'估算盈余 ')+Math.round(Math.abs(day.deficit))+' kcal'}
function nLatestMeasurement(date=nDate()){return [...nutrition.measurements].reverse().filter(m=>m.date<=date).sort((a,b)=>b.date.localeCompare(a.date)||(b.localTime||'').localeCompare(a.localTime||'')||b.createdAt-a.createdAt)[0]||null}
function nWeightOptions(){
  document.getElementById('nutrition-weight-candidate')?.remove?.();
  const input=document.getElementById('sport-weight')||document.getElementById('estimate-weight');
  if(!input?.closest?.('form'))return;
  const date=input.id==='sport-weight'?document.getElementById('sport-date')?.value:nDate(new Date(draft?.startedAt||Date.now()));
  const candidate=nValidDate(date)?nLatestMeasurement(date):null;
  if(candidate)input.insertAdjacentHTML?.('afterend','<button id="nutrition-weight-candidate" type="button" class="text-button" data-nut-action="use-body-weight" data-id="'+candidate.id+'" data-input="'+input.id+'">使用最近测量 '+candidate.weightKg+' kg · '+candidate.date+'</button>');
}
function homeNutritionCard(){const day=nutritionDay(nDate()),body=nLatestMeasurement();return '<section class="card home-nutrition"><div class="card-head"><h2>饮食与身体</h2><button class="text-button" data-nut-action="meal-new">记一餐</button></div><button class="n-home-summary" data-page="nutrition"><strong>'+(nutritionProblem?'数据待核对':day.meals.length?(day.unknown?'已知部分 ':'已记 ')+Math.round(day.known)+' kcal':'今天尚未记饮食')+'</strong><span>'+escapeHTML(nGapText(day))+' ›</span></button><div class="n-body-quick"><span>'+escapeHTML(body?'最近体重 '+body.weightKg+' kg · '+body.date.slice(5):'还没有体重记录')+'</span><button class="text-button" data-nut-action="body-new">记体重</button></div></section>'}
let nutritionDate=nDate(),bodyMetric='weight',bodyRange=30,bodyLimit=20,nutritionModal='',mealEditor=null,nEditorTimer,nEditorDirty=false,nOrigin=null,nBodyEditing=null;
function nBanner(){return nutritionProblem?'<p class="n-warning">'+escapeHTML(nutritionProblem)+'</p>':nutritionConflict?'<p class="n-warning">其他窗口已更新。当前草稿可以导出后重新载入。</p><button class="text-button" data-nut-action="draft-export">导出当前草稿</button><button class="text-button" data-nut-action="reload">重新载入饮食与身体数据</button>':''}
function nDateBar(){return '<div class="n-date-bar"><button data-nut-action="date-prev" aria-label="前一天">‹</button><label><span class="small-label">查看日期</span><input id="nutrition-date" type="date" max="'+nDate()+'" value="'+nutritionDate+'"></label><button data-nut-action="date-next" aria-label="后一天" '+(nutritionDate===nDate()?'disabled':'')+'>›</button><button class="text-button" data-nut-action="date-today">今天</button></div>'}
function nutritionPage(){
  const day=nutritionDay(nutritionDate),skipped=nutrition.dayStates[nutritionDate]?.skipped||[];
  return heading('FOOD & ENERGY','饮食记录','记下每一餐，回看摄入与训练。','<button class="primary-button" data-nut-action="meal-new">记一餐</button>')+nBanner()+nDateBar()+
  '<section class="card n-energy"><div class="card-head"><h2>'+(day.unknown?'已知部分摄入':'已记摄入')+'</h2><button class="text-button" data-nut-action="target">饮食目标</button></div><strong class="n-big">'+(day.meals.length?Math.round(day.known).toLocaleString():'—')+'<small> kcal</small></strong><p>'+escapeHTML(nDifference(day.remaining))+'</p><p class="small-label">'+(day.plan?'目标 '+day.plan.targetKcal+' kcal · '+(day.plan.tdeeKcal?'全天维持消耗参考 '+day.plan.tdeeKcal+' kcal':'维持消耗未填'):'设置目标后显示距目标差额')+'</p><div class="n-gap">'+escapeHTML(nGapText(day))+'</div><p class="small-label">热量为参考估算，非实测。'+(nutritionDate===nDate()&&day.complete?'截至当前，按全天消耗估算。':'')+'运动估算单独展示，不再加到全天消耗。</p></section>'+
  (nutrition.mealDraft?'<section class="n-draft-banner"><span>有一餐草稿待保存 · 不计入摄入</span><button class="text-button" data-nut-action="meal-resume">继续登记</button></section>':'')+
  '<div class="n-meals">'+mealTypes.map(([key,label])=>{const list=day.meals.filter(m=>m.mealType===key);return '<section class="card"><div class="card-head"><h2>'+label+'</h2><button class="text-button" data-nut-action="meal-new" data-meal-type="'+key+'">添加</button></div>'+(list.length?list.map(m=>'<button class="n-row" data-nut-action="meal-detail" data-id="'+escapeHTML(m.id)+'"><span><strong>'+escapeHTML(m.name)+'</strong><small>'+escapeHTML(m.items.map(i=>i.name).join('、'))+'</small></span><span>'+nKcal(nMealCalories(m).unknown?null:nMealCalories(m).known)+' ›</span></button>').join(''):'<div class="n-empty-meal"><span>'+ (skipped.includes(key)?'未吃（已标记）':'未记录')+'</span><button class="text-button" data-nut-action="meal-skip" data-meal-type="'+key+'">'+(skipped.includes(key)?'取消未吃':'标记未吃')+'</button></div>')+'</section>'}).join('')+'</div><button class="secondary-button n-full" data-nut-action="confirm-day" '+(!day.meals.length?'disabled':'')+'>'+(day.complete?'已确认记全 · 取消确认':'确认当天饮食已记全')+'</button>'+nutritionSuggestions(day)+'<section class="card"><div class="card-head"><h2>当日训练与测量</h2><button class="text-button" data-nut-action="day-review">当日回顾</button></div><p class="small-label">'+nutritionTrainingSummary(nutritionDate,nutritionDate)+'</p></section>'+nutritionPeriodSummary();
}
function nutritionTrainingSummary(from,to){const selected=records.filter(r=>r.date>=from&&r.date<=to),total=summary(selected);return total.count+' 次训练 · '+total.minutes+' 分钟 · '+total.sets+' 组 · '+total.volume.toLocaleString()+' kg 吨位'}
function nutritionPeriodSummary(){const start=nShift(nutritionDate,-6),days=Array.from({length:7},(_,i)=>nutritionDay(nShift(start,i))),logged=days.filter(d=>d.meals.length),valid=days.filter(d=>d.deficit!==null);return '<section class="card"><h2>最近七天</h2><p class="subtitle">'+start+' 至 '+nutritionDate+'</p><p>已记 '+logged.length+'/7天 · 记全 '+days.filter(d=>d.complete).length+'/7天</p><p class="small-label">'+(valid.length?'估算平均缺口 '+Math.round(valid.reduce((n,d)=>n+d.deficit,0)/valid.length)+' kcal · 有效 '+valid.length+'/7天（负值为盈余）':'暂无有效缺口日')+'；漏记日不算零摄入。</p></section>'}
function nutritionSuggestions(day){
  const choices=[];
  if(day.meals.length&&(!day.complete||day.unknown))choices.push(['day-review','先检查饮料、酱料和加餐，再确认今天是否记全。']);
  if(day.meals.some(m=>m.items.some(i=>['cola','sprite'].includes(i.foodId))))choices.push(['combos','下次可考虑无糖饮料或水，在保存前复核实际规格。']);
  if(day.complete&&!day.unknown&&day.plan&&day.known<day.plan.targetKcal*.8)choices.push(['day-review','已记摄入明显低于所设目标，先核对漏记与恢复状态。']);
  else if(day.complete&&!day.unknown&&day.remaining<0)choices.push(['day-review','今日比目标多约 '+Math.round(-day.remaining)+' kcal，可回看饮料与份量。']);
  if(!nLatestMeasurement()||nLatestMeasurement().date<nShift(nDate(),-7))choices.push(['body-new','在相近条件下记一次体重，方便回看训练期间的变化。']);
  if(!choices.length)choices.push(['day-review','结合连续记录回看饮食和训练，不按一天体重波动调整目标。']);
  return '<section class="card n-suggestions"><h2>可以做的下一步</h2>'+choices.slice(0,2).map(([action,label])=>'<button class="n-row" data-nut-action="'+action+'"><span>'+escapeHTML(label)+'</span><span>›</span></button>').join('')+'</section>';
}
function nRepresentative(date,data=nutrition){const list=data.measurements.filter(m=>m.date===date).sort((a,b)=>(a.localTime||'23:59').localeCompare(b.localTime||'23:59')||a.createdAt-b.createdAt);return list.find(m=>m.id===data.representativeByDate[date])||list[0]||null}
function nMean(date,days=7,data=nutrition){const values=Array.from({length:days},(_,i)=>nRepresentative(nShift(date,-i),data)).filter(Boolean);return {count:values.length,value:values.length>=3?values.reduce((n,m)=>n+m.weightKg,0)/values.length:null}}
function nWeekChange(data=nutrition){const monday=nShift(nDate(),-(new Date().getDay()+6)%7),thisValues=Array.from({length:7},(_,i)=>nRepresentative(nShift(monday,i),data)).filter(Boolean),previous=nMean(nShift(monday,-1),7,data);return {count:thisValues.length,previousCount:previous.count,value:thisValues.length>=3&&previous.value!==null?thisValues.reduce((n,m)=>n+m.weightKg,0)/thisValues.length-previous.value:null}}
function bodyChart(){
  const end=nDate(),start=nShift(end,1-bodyRange),dates=Array.from({length:bodyRange},(_,i)=>nShift(start,i)),points=dates.map(date=>{const m=nRepresentative(date);return {date,m,value:bodyMetric==='weight'?m?.weightKg??null:m?.bodyFatPercent??null}}),known=points.filter(p=>p.value!==null);
  if(!known.length)return '<p class="n-empty">这个周期还没有'+(bodyMetric==='weight'?'体重':'体脂率')+'记录。</p>';
  const low=Math.min(...known.map(p=>p.value)),high=Math.max(...known.map(p=>p.value)),span=Math.max(bodyMetric==='weight'?1:2,high-low),min=low-span*.15,max=high+span*.15;
  const x=i=>30+i/(bodyRange-1)*560,y=v=>170-(v-min)/(max-min)*140;
  let segments=[],current=[];points.forEach((p,i)=>{if(p.value===null){if(current.length)segments.push(current);current=[]}else current.push(x(i)+','+y(p.value))});if(current.length)segments.push(current);
  const last=known[known.length-1],first=known[0],change=last.value-first.value,mean=nMean(end);
  return '<svg class="n-chart" viewBox="0 0 620 210" role="img" aria-label="'+escapeHTML((bodyMetric==='weight'?'体重':'体脂率')+'趋势，每日代表值，缺失日期断点')+'"><text x="4" y="20">'+high.toFixed(1)+'</text><text x="4" y="184">'+low.toFixed(1)+'</text><path d="M30 175H595" stroke="#e1e6ee"/>'+segments.map(s=>'<polyline points="'+s.join(' ')+'" fill="none" stroke="#315cff" stroke-width="2.5"/>').join('')+points.map((p,i)=>p.value===null?'':'<circle cx="'+x(i)+'" cy="'+y(p.value)+'" r="4" fill="#315cff"><title>'+p.date+' '+p.value+(bodyMetric==='weight'?'kg':'%')+'</title></circle>').join('')+'<text x="30" y="202">'+start.slice(5)+'</text><text x="552" y="202">'+end.slice(5)+'</text></svg><p class="small-label">每日代表值 · 默认最早一次 · 缺失日不填零</p><p class="subtitle">'+first.date+' → '+last.date+'：'+(change>0?'增加':change<0?'下降':'变化')+' '+Math.abs(change).toFixed(bodyMetric==='weight'?2:1)+(bodyMetric==='weight'?' kg':' 个百分点')+'</p>'+(bodyMetric==='weight'?'<p class="small-label">最近7天均重 '+(mean.value===null?'记录不足':mean.value.toFixed(2)+' kg')+' · 样本 '+mean.count+'/7天</p>':'');
}
function bodyPage(){const latest=nLatestMeasurement(),lastFat=[...nutrition.measurements].filter(m=>m.bodyFatPercent!==null).sort((a,b)=>b.date.localeCompare(a.date)||b.createdAt-a.createdAt)[0],list=[...nutrition.measurements].sort((a,b)=>b.date.localeCompare(a.date)||(b.localTime||'').localeCompare(a.localTime||'')||b.createdAt-a.createdAt),change=nWeekChange();return nBanner()+'<section class="card"><div class="card-head"><h2>身体记录</h2><button class="primary-button" data-nut-action="body-new">记体重</button></div><strong class="n-big">'+(latest?latest.weightKg:'—')+'<small> kg</small></strong><p class="subtitle">'+(latest?escapeHTML(latest.date+' '+(latest.localTime||'时间未记录')):'还没有测量记录')+'</p><p>'+ (latest?.bodyFatPercent!==null&&latest?.bodyFatPercent!==undefined?'体脂率 '+latest.bodyFatPercent+'% · 同次测量':'本次未测体脂'+(lastFat?' · 上次 '+lastFat.bodyFatPercent+'%（'+lastFat.date+'）':''))+'</p><p class="small-label">同一设备、相近条件更便于比较。体脂秤读数受水分等影响，趋势仅供参考。</p></section><section class="card"><div class="project-tabs">'+[['weight','体重'],['fat','体脂率']].map(([id,label])=>'<button data-nut-action="body-metric" data-value="'+id+'" aria-pressed="'+(bodyMetric===id)+'">'+label+'</button>').join('')+'</div><div class="n-range">'+[7,30,90].map(days=>'<button data-nut-action="body-range" data-value="'+days+'" aria-pressed="'+(bodyRange===days)+'">'+days+'天</button>').join('')+'</div><div id="body-chart">'+bodyChart()+'</div><p class="small-label">本周与上周均重：'+(change.value===null?'记录不足':(change.value>=0?'+':'')+change.value.toFixed(2)+' kg')+' · 本周'+change.count+'天 / 上周'+change.previousCount+'天 · 截至今日</p></section><section class="card"><h2>同周期训练与饮食</h2><p class="subtitle">'+nutritionTrainingSummary(nShift(nDate(),1-bodyRange),nDate())+'</p><p class="small-label">'+bodyDietSummary()+'。并列回看，不推断训练导致了身体变化。</p></section><section class="card"><h2>测量历史</h2>'+ (list.length?list.slice(0,bodyLimit).map(m=>'<button class="n-row" data-nut-action="body-edit" data-id="'+escapeHTML(m.id)+'"><span><strong>'+m.weightKg+' kg'+(m.bodyFatPercent===null?'':' · '+m.bodyFatPercent+'%')+'</strong><small>'+escapeHTML(m.date+' '+(m.localTime||'时间未记录')+' · '+bodyMethods.find(([id])=>id===m.method)[1])+'</small></span><span>编辑 ›</span></button>').join(''):'<p class="n-empty">还没有身体测量，记一条开始观察。</p>')+(list.length>bodyLimit?'<button class="text-button" data-nut-action="body-more">查看更多测量</button>':'')+'</section>'}
function bodyDietSummary(){const days=Array.from({length:bodyRange},(_,i)=>nutritionDay(nShift(nDate(),-i)));return '已记 '+days.filter(d=>d.meals.length).length+'/'+bodyRange+'天 · 记全 '+days.filter(d=>d.complete).length+'天 · 有效缺口 '+days.filter(d=>d.deficit!==null).length+'天'}
function nRefresh(){const scroll=window.scrollY||0;render();window.scrollTo?.(0,scroll)}
function nHeader(title,back=''){return '<div class="dialog-header"><h2 id="nutrition-title" tabindex="-1">'+escapeHTML(title)+'</h2>'+(back?'<button class="text-button" data-nut-action="'+back+'">返回</button>':'')+'<button class="close-button" data-nut-action="close" aria-label="关闭饮食与身体窗口">'+icon('close',17)+'</button></div>'}
function nShow(mode,content){nutritionModal=mode;const dialog=document.getElementById('nutrition-dialog');if(!dialog.open)nOrigin={element:document.activeElement,scroll:window.scrollY||0};document.getElementById('nutrition-content').innerHTML='<div class="dialog-content">'+content+'<p id="nutrition-error" role="alert" class="n-error"></p></div>';if(!dialog.open)dialog.showModal();dialog.scrollTop=0;document.getElementById('nutrition-title')?.focus?.({preventScroll:true})}
function nDismiss(){nutritionModal='';document.getElementById('nutrition-dialog').close();nRefresh();const origin=nOrigin?.element;const target=origin?.isConnected?origin:[...document.querySelectorAll?.('button')||[]].find(b=>Object.keys(origin?.dataset||{}).length&&Object.entries(origin.dataset).every(([key,value])=>b.dataset[key]===value)&&b.getClientRects?.().length);target?.focus?.({preventScroll:true});window.scrollTo?.(0,nOrigin?.scroll||0);nOrigin=null}
function nField(id,label,value='',type='text',attrs=''){return '<div class="field"><label for="'+id+'">'+label+'</label><input id="'+id+'" name="'+id+'" type="'+type+'" value="'+escapeHTML(value??'')+'" '+attrs+'></div>'}
function nFormValues(form){return Object.fromEntries(new FormData(form))}
function nNewItem(food,quantity=food.portion){return {id:nId(),foodId:food.id,name:food.name,unit:food.unit,quantity,basis:nClone(food.basis),note:food.note||'',region:food.region||'CN',sourceSnapshot:{...nClone(foodSources[food.source]||foodSources.manual),version:food.dataVersion||foodDataVersion,checkedAt:food.checkedAt||null,recipe:nClone(food.recipe||null),menuSource:nClone(food.menuSource||null),reference:nClone(food.reference||null)}}}
function nFoodList(query='',category='全部'){const q=query.trim().toLowerCase(),custom=nutrition.customFoods.map(i=>({id:i.foodId,name:i.name,category:'我的食品',unit:i.unit,basis:i.basis,portion:i.quantity,source:'manual',note:i.note,aliases:[]}));return [...foodCatalog,...custom].filter(f=>(category==='全部'||f.category===category)&&(!q||f.name.toLowerCase().includes(q)||f.category.toLowerCase().includes(q)||f.aliases.some(a=>a.toLowerCase().includes(q)))).sort((a,b)=>Number(b.name.toLowerCase().includes(q))-Number(a.name.toLowerCase().includes(q)))}
function nComboItems(combo){return combo.items.map(item=>Array.isArray(item)?nNewItem(foodCatalog.find(f=>f.id===item[0]),item[1]):{...nClone(item),id:nId()})}
async function nStartMeal(type='',id='',copy=false){
  if(!nWritable())return;
  if(nutrition.mealDraft&&!id){mealEditor=nClone(nutrition.mealDraft);nShow('resume-choice',nHeader('有一餐草稿未保存')+'<p>继续登记，或放弃草稿后开始新一餐。</p><div class="n-actions"><button class="primary-button" data-nut-action="meal-resume">继续草稿</button><button class="secondary-button" data-nut-action="meal-discard-new" data-meal-type="'+type+'">放弃并新建</button></div>');return}
  if(nutrition.mealDraft&&id){nError('请先保存或放弃现有草稿，再编辑其他餐。');return}
  const meal=nutrition.meals.find(m=>m.id===id),hour=new Date().getHours();
  const editor={id:copy||!meal?nId():meal.id,editId:copy?'':meal?.id||'',sourceRevision:copy?null:meal?.revision||null,date:meal&&!copy?meal.date:nutritionDate,mealType:meal?.mealType||type|| (hour<10?'breakfast':hour<15?'lunch':'dinner'),name:meal?.name||'',note:meal?.note||'',items:meal?nClone(meal.items):[],energyMode:meal?.energyMode||'items',manualEnergyKcal:meal?.manualEnergyKcal??null,step:meal?'params':'picker',picker:'frequent',query:'',category:'全部'};
  if(await nCommit(next=>{next.mealDraft=editor})){mealEditor=nClone(editor);nEditorDirty=false;nMealRender()}
}
async function nPersistEditor(){clearTimeout(nEditorTimer);if(!mealEditor)return true;const snapshot=nClone(mealEditor);const ok=await nCommit(next=>{next.mealDraft=snapshot});if(ok)nEditorDirty=mealEditor!==null&&JSON.stringify(mealEditor)!==JSON.stringify(snapshot);const status=document.getElementById('meal-draft-status');if(status)status.textContent=ok?'草稿已保存，尚未计入摄入。':'草稿保存失败；填写内容在当前窗口保留，请重试。';return ok}
function nQueueEditor(){nEditorDirty=true;clearTimeout(nEditorTimer);nEditorTimer=setTimeout(()=>{nPersistEditor()},350)}
function nFrequentItems(){const seen=new Set(),items=[];for(const meal of [...nutrition.meals].sort((a,b)=>b.updatedAt-a.updatedAt))for(const i of meal.items)if(!seen.has(i.foodId)){seen.add(i.foodId);items.push(i)}return items.slice(0,8)}
function nPickerResults(){if(!mealEditor)return '';if(mealEditor.picker==='frequent'){const recent=nFrequentItems();return (nutrition.favoriteCombos.length?'<h3>我的常吃组合</h3>'+nutrition.favoriteCombos.map(c=>'<button class="n-row" data-nut-action="combo-add" data-id="'+escapeHTML(c.id)+'"><span>'+escapeHTML(c.name)+'</span><span>添加 ›</span></button>').join(''):'')+(recent.length?'<h3>最近吃过</h3>'+recent.map(i=>'<button class="n-row" data-nut-action="recent-add" data-id="'+escapeHTML(i.foodId)+'"><span>'+escapeHTML(i.name)+'</span><span>添加 ›</span></button>').join(''):'<p class="n-empty">还没有常吃记录。先搜索食物，或浏览参考组合。</p>')+'<button class="secondary-button n-full" data-nut-action="combos">浏览参考组合</button>'}
  return nFoodList(mealEditor.query,mealEditor.category).map(f=>'<button class="n-row" data-nut-action="food-add" data-id="'+f.id+'"><span><strong>'+escapeHTML(f.name)+'</strong><small>'+escapeHTML(f.portion+f.unit+' · '+(foodSources[f.source]?.type||'用户手填')+' · '+f.note)+'</small></span><span>'+nKcal(f.basis.energyKcal===null?null:f.portion/f.basis.amount*f.basis.energyKcal)+' ＋</span></button>').join('')||'<p class="n-empty">未找到，可自定义食品。</p>';
}
function nMealRender(){
  if(!mealEditor)return;const e=mealEditor;
  if(e.step==='picker')nShow('meal-picker',nHeader('记一餐 · 选择食物')+'<div class="project-tabs">'+[['frequent','常吃'],['search','搜索']].map(([id,label])=>'<button data-nut-action="picker-tab" data-value="'+id+'" aria-pressed="'+(e.picker===id)+'">'+label+'</button>').join('')+'</div>'+(e.picker==='search'?nField('nutrition-search','搜索食品',e.query,'search','placeholder="米饭、意面、麦当劳、柠檬茶"')+'<div class="field"><label for="nutrition-category">分类</label><select id="nutrition-category">'+['全部',...new Set(foodCatalog.map(f=>f.category)),'我的食品'].map(c=>'<option '+(e.category===c?'selected':'')+'>'+c+'</option>').join('')+'</select></div>':'')+'<div id="nutrition-picker-results">'+nPickerResults()+'</div><button class="text-button n-full" data-nut-action="custom-food">自定义食品 / 标签热量</button><div class="n-picker-footer"><span id="nutrition-selection">已选 '+e.items.length+' 项</span><button class="primary-button" data-nut-action="meal-next" '+(!e.items.length?'disabled':'')+'>下一步</button></div><p class="small-label">参考份量可修改；待填写热量的食品不会计作0。</p>');
  else nShow('meal-params',nHeader(e.editId?'编辑这餐':'记一餐 · 份量与热量','meal-back')+'<form id="nutrition-meal-form" class="profile-form">'+nField('meal-date','日期',e.date,'date','max="'+nDate()+'" required')+'<div class="field"><label for="meal-type">餐次</label><select id="meal-type" name="meal-type">'+mealTypes.map(([id,label])=>'<option value="'+id+'" '+(e.mealType===id?'selected':'')+'>'+label+'</option>').join('')+'</select></div>'+nField('meal-name','餐名（可空）',e.name,'text','maxlength="60"')+nField('meal-note','备注（可空）',e.note,'text','maxlength="300"')+'<div class="field full"><label for="meal-energy-mode">热量记录方式</label><select id="meal-energy-mode"><option value="items" '+(e.energyMode==='items'?'selected':'')+'>分项计算</option><option value="manual" '+(e.energyMode==='manual'?'selected':'')+'>整餐手填（不再叠加分项）</option></select></div><div class="field full" id="meal-manual-field" '+(e.energyMode==='manual'?'':'hidden')+'>'+nField('meal-manual','整餐热量 / kcal',e.manualEnergyKcal,'number','min="0" max="20000" step="0.1"')+'</div><section class="full n-item-list">'+e.items.map((item,index)=>nItemForm(item,index)).join('')+'</section><p id="meal-total" class="full n-total" role="status">'+nMealTotalText()+'</p><div class="full n-actions"><button type="button" class="secondary-button" data-nut-action="meal-back">继续加食品</button><button type="submit" class="primary-button">保存这餐</button></div></form><button class="text-button n-full" data-nut-action="favorite-combo">保存为常吃组合</button><p id="meal-draft-status" class="small-label" role="status">草稿已保存，尚未计入摄入。</p>');
}
function nItemForm(item,index){return '<article class="n-item"><div class="card-head"><h3>'+escapeHTML(item.name)+'</h3><button type="button" class="text-button" data-nut-action="item-remove" data-index="'+index+'">移除</button></div><p class="small-label">'+escapeHTML(item.note)+'</p><div class="n-item-fields"><div class="field"><label for="meal-qty-'+index+'">份量 / '+item.unit+'</label><input id="meal-qty-'+index+'" data-nut-field="quantity" data-index="'+index+'" type="number" min="'+(['g','ml'].includes(item.unit)?'0.1':'0.5')+'" max="'+(['g','ml'].includes(item.unit)?'10000':'100')+'" step="'+(['g','ml'].includes(item.unit)?'0.1':'0.5')+'" required value="'+item.quantity+'"></div><div class="field"><label for="meal-energy-'+index+'">每'+item.basis.amount+item.unit+' / kcal</label><input id="meal-energy-'+index+'" data-nut-field="energy" data-index="'+index+'" type="number" min="0" max="20000" step="any" value="'+(item.basis.energyKcal??'')+'" placeholder="未知可空"></div></div><div class="n-portions">'+[[.5,'半份'],[1,'参考一份'],[2,'两份']].map(([value,label])=>'<button type="button" data-nut-action="portion" data-index="'+index+'" data-value="'+value+'">'+label+'</button>').join('')+'<button type="button" class="text-button" data-nut-action="food-source" data-index="'+index+'">估算依据</button></div></article>'}
function nMealTotalText(){const c=nMealCalories(mealEditor);return c.unknown?'已知部分约 '+Math.round(c.known)+' kcal · '+c.unknown+' 项待填热量':nKcal(c.known)}
function nReadMealForm(){if(!mealEditor||nutritionModal!=='meal-params')return;const e=mealEditor;for(const [field,id]of [['date','meal-date'],['mealType','meal-type'],['name','meal-name'],['note','meal-note'],['energyMode','meal-energy-mode']])e[field]=document.getElementById(id).value;const manual=document.getElementById('meal-manual').value;e.manualEnergyKcal=manual===''?null:Number(manual);e.items.forEach((i,index)=>{i.quantity=Number(document.getElementById('meal-qty-'+index).value);const text=document.getElementById('meal-energy-'+index).value,value=text===''?null:Number(text);if(i.basis.energyKcal!==value){i.basis.energyKcal=value;i.sourceSnapshot=nClone(foodSources.manual)}})}
async function nSaveMeal(){
  nReadMealForm();clearTimeout(nEditorTimer);const e=nClone(mealEditor);if(!e)return false;
  const total=nMealCalories(e),meal={...e,name:e.name.trim()||mealTypes.find(([id])=>id===e.mealType)?.[1]||'饮食',note:e.note.trim(),revision:1,createdAt:Date.now(),updatedAt:Date.now()};
  if(!nValidMeal(meal)||total.known>20000)return nError('请核对日期、份量与热量；整餐热量应为0–20000 kcal，未知分项可留空。');
  if(!e.items.every(i=>['g','ml'].includes(i.unit)?Math.abs(i.quantity*10-Math.round(i.quantity*10))<1e-7:Number.isInteger(i.quantity*2)))return nError('克/ml最多一位小数，个/块/份按半份填写。');
  const ok=await nCommit(next=>{const old=next.meals.find(m=>m.id===e.id);if(e.editId&&(!old||old.revision!==e.sourceRevision))return nError('原餐记录已变化，请保留草稿后重新载入核对。');if(!e.editId&&old)return nError('这餐已经保存，不能重复添加。');if(old){meal.createdAt=old.createdAt;meal.revision=old.revision+1;if(old.date!==meal.date)nTouchDay(next,old.date)}next.meals=[...next.meals.filter(m=>m.id!==meal.id),meal];nTouchDay(next,meal.date);next.dayStates[meal.date].skipped=(next.dayStates[meal.date].skipped||[]).filter(t=>t!==meal.mealType);next.mealDraft=null});
  if(ok){nutritionDate=meal.date;mealEditor=null;nEditorDirty=false;nDismiss();toast('这餐已保存 · '+(total.unknown?'含待填热量项目':nKcal(total.known)))}return ok;
}
function nMealDetail(id){const m=nutrition.meals.find(meal=>meal.id===id);if(!m)return;nShow('meal-detail',nHeader(m.name)+'<p class="subtitle">'+m.date+' · '+mealTypes.find(([key])=>key===m.mealType)[1]+'</p><p class="n-total">'+(nMealCalories(m).unknown?'已知部分 '+nKcal(nMealCalories(m).known):nKcal(nMealCalories(m).known))+'</p>'+m.items.map(i=>'<div class="n-row"><span>'+escapeHTML(i.name)+'<small>'+i.quantity+i.unit+'</small></span><span>'+nKcal(nItemCalories(i))+'</span></div>').join('')+'<p class="small-label">'+escapeHTML(m.energyMode==='manual'?'已使用整餐手填热量，不叠加分项。':m.note)+'</p><div class="n-actions"><button class="primary-button" data-nut-action="meal-edit" data-id="'+m.id+'">编辑这餐</button><button class="secondary-button" data-nut-action="meal-copy" data-id="'+m.id+'">复制到当前日期</button></div><button class="text-button n-full" data-nut-action="meal-delete-prompt" data-id="'+m.id+'">删除这餐</button>')}
async function nDeleteMeal(id){const ok=await nCommit(next=>{const meal=next.meals.find(m=>m.id===id);if(!meal)return false;next.meals=next.meals.filter(m=>m.id!==id);nTouchDay(next,meal.date)});if(ok){nDismiss();toast('这餐已删除，请重新确认当天是否记全')}return ok}
async function nConfirmDay(date){const ok=await nCommit(next=>{const day=nutritionDay(date,next);if(!day.meals.length)return nError('请先记录饮食。');const state=next.dayStates[date];state.confirmedRevision=day.complete?null:state.revision;state.confirmedAt=day.complete?null:Date.now()});if(ok){nRefresh();toast(nutritionDay(date).complete?'已确认记全；未知热量仍需补填':'已取消记全确认')}return ok}
let nutritionComboCategory='全部';
function nComboResults(){return foodCombos.filter(c=>nutritionComboCategory==='全部'||c.category===nutritionComboCategory).map(c=>{const items=nComboItems(c),total=nMealCalories({items,energyMode:'items'});return '<button class="n-row" data-nut-action="combo-add" data-id="'+c.id+'"><span><strong>'+escapeHTML(c.name)+'</strong><small>'+escapeHTML(items.map(i=>i.name).join('、'))+'</small></span><span>'+ (total.unknown?'含待填项':nKcal(total.known))+' ＋</span></button>'}).join('')}
function nCombos(){if(!mealEditor){nStartMeal().then(()=>{if(mealEditor)nCombos()});return}nShow('combos',nHeader('参考组合','meal-picker-return')+'<p class="small-label">选择后可改分项份量。店铺搭配为独立参考，不是官方套餐热量；饭、酱料和汤底是否已含在菜名与配方中说明。</p><div class="field"><label for="nutrition-combo-category">店铺 / 组合类型</label><select id="nutrition-combo-category">'+['全部',...new Set(foodCombos.map(c=>c.category))].map(c=>'<option '+(c===nutritionComboCategory?'selected':'')+'>'+escapeHTML(c)+'</option>').join('')+'</select></div><div id="nutrition-combo-results">'+nComboResults()+'</div>')}
function nCustomFood(){nShow('custom-food',nHeader('自定义食品','meal-picker-return')+'<form id="nutrition-custom-form" class="profile-form">'+nField('custom-name','食品名称','','text','maxlength="60" required')+'<div class="field"><label for="custom-unit">单位</label><select id="custom-unit" name="custom-unit"><option>份</option><option>g</option><option>ml</option><option>个</option><option>块</option></select></div>'+nField('custom-amount','标签基准量 / 对应单位',1,'number','min="0.1" max="10000" step="0.1" required')+nField('custom-energy','基准量热量（未知可空）','','number','min="0" max="20000" step="0.1"')+'<div class="field"><label for="custom-energy-unit">能量单位</label><select id="custom-energy-unit" name="custom-energy-unit"><option value="kcal">kcal / 千卡</option><option value="kj">kJ / 千焦</option></select></div><label class="full"><input type="checkbox" name="custom-remember" checked> 保存到我的食品，方便下次登记</label><button class="primary-button full" type="submit">添加到这餐</button></form>')}
async function nAddCustom(values){const amount=Number(values['custom-amount']),energy=values['custom-energy']===''?null:Number(values['custom-energy'])/(values['custom-energy-unit']==='kj'?4.184:1),name=String(values['custom-name']||'').trim(),unit=values['custom-unit'];const item={id:nId(),foodId:nId(),name,unit,quantity:amount,basis:{amount,unit,energyKcal:energy},sourceSnapshot:nClone(foodSources.manual),note:'用户填写；可按实际标签修改'};if(!nValidItem(item))return nError('请填写有效名称、基准量和热量。');if(values['custom-remember']){if(!await nCommit(next=>{next.customFoods.push(item);next.mealDraft={...nClone(mealEditor),items:[...mealEditor.items,item]}}))return false;mealEditor=nClone(nutrition.mealDraft)}else{mealEditor.items.push(item);if(!await nPersistEditor())return false}mealEditor.step='params';nMealRender();return true}
function nTargetDialog(){const p=nEffectivePlan(nDate());nShow('target',nHeader('饮食目标')+'<p class="small-label">填写每日饮食目标；维持消耗可空，是包含通常运动的全天估算总量。不会再加运动热量，也不会改变训练计划。</p><form id="nutrition-target-form" class="profile-form">'+nField('target-kcal','每日饮食目标 / kcal',p?.targetKcal??'','number','min="1" max="20000" step="1" required')+nField('target-tdee','全天维持消耗 / kcal（可空）',p?.tdeeKcal??'','number','min="1" max="20000" step="1"')+'<div class="field full"><label for="target-goal">饮食方向</label><select id="target-goal" name="target-goal">'+[['maintain','维持'],['lose','减脂'],['gain','增肌']].map(([id,label])=>'<option value="'+id+'" '+(p?.goal===id?'selected':'')+'>'+label+'</option>').join('')+'</select></div><label class="full"><input type="checkbox" name="target-today" '+(!nutrition.dayStates[nDate()]?'checked':'')+'> 将新目标应用到今天（替换今天快照，过去日期不变）</label><p class="small-label full">未勾选时从明天生效。自动活动估算与自动减脂建议尚未启用；可填写你已确认的参考值。</p><button class="primary-button full" type="submit">保存目标</button></form>')}
async function nSaveTarget(values){const target=Number(values['target-kcal']),raw=values['target-tdee'],tdee=raw===''?null:Number(raw),today=!!values['target-today'];const p={id:nId(),effectiveFrom:today?nDate():nShift(nDate(),1),createdAt:Date.now(),method:'manual',goal:values['target-goal'],targetKcal:target,tdeeKcal:tdee,inputs:{},formulaVersion:'manual-v1',sources:[]};/* Future plan dates are allowed; validateNutrition separately validates them. */if(!Number.isInteger(target)||!nFinite(target,1,20000)||(tdee!==null&&(!Number.isInteger(tdee)||!nFinite(tdee,1,20000)))||!['maintain','lose','gain'].includes(p.goal))return nError('请填写1–20000的整数目标；维持消耗可留空。');const ok=await nCommit(next=>{next.energyPlans.push(p);if(today&&next.dayStates[nDate()]){next.dayStates[nDate()].energyPlanSnapshot=nClone(p)}});if(ok){nDismiss();toast('目标已保存 · '+(today?'今天起':'明天起')+'生效')}return ok}
function nBodyForm(id=''){nBodyEditing=nutrition.measurements.find(m=>m.id===id)||null;const m=nBodyEditing,now=new Date(),time=m?.localTime??(m?'':String(now.getHours()).padStart(2,'0')+':'+String(now.getMinutes()).padStart(2,'0'));nShow('body-form',nHeader(m?'编辑身体测量':'记录体重与体脂')+'<form id="nutrition-body-form" class="profile-form">'+nField('body-date','测量日期',m?.date||nDate(),'date','max="'+nDate()+'" required')+nField('body-time','测量时刻（补记可空）',time,'time')+nField('body-weight','体重 / kg',m?.weightKg??'','number','min="20" max="300" step="0.01" required')+nField('body-fat','体脂率 / %（可空）',m?.bodyFatPercent??'','number','min="0.1" max="99.9" step="0.1"')+'<div class="field"><label for="body-method">测量来源</label><select id="body-method" name="body-method">'+bodyMethods.map(([key,label])=>'<option value="'+key+'" '+(m?.method===key?'selected':'')+'>'+label+'</option>').join('')+'</select></div>'+nField('body-device','设备（可空）',m?.device||'','text','maxlength="60"')+nField('body-note','备注（可空）',m?.note||'','text','maxlength="300"')+'<p class="small-label full" id="body-existing">当天已有 '+nutrition.measurements.filter(x=>x.date===(m?.date||nDate())&&x.id!==m?.id).length+' 条测量；保存会'+(m?'修改本条':'新增一条，不覆盖已有测量')+'。</p><button class="primary-button full" type="submit">保存测量</button></form>'+(m?'<div class="n-actions"><button class="secondary-button" data-nut-action="body-representative" data-id="'+m.id+'">设为当天代表值</button><button class="secondary-button" data-nut-action="day-review" data-date="'+m.date+'">当日回顾</button></div><div class="n-actions"><button class="text-button" data-nut-action="body-sync" data-id="'+m.id+'">同步到资料体重</button><button class="text-button" data-nut-action="body-delete-prompt" data-id="'+m.id+'">删除测量</button></div>':'')+'<p class="small-label">体脂不填即未测，不用体重推算。保存不改变资料、训练计划或历史运动热量。</p>')}
async function nSaveBody(values,id=nBodyEditing?.id||''){
  const weight=Number(values['body-weight']),fat=values['body-fat']===''?null:Number(values['body-fat']),time=values['body-time']||null,date=values['body-date'],old=nutrition.measurements.find(m=>m.id===id);
  const m={id:id||nId(),date,localTime:time,weightKg:weight,bodyFatPercent:fat,method:values['body-method'],device:String(values['body-device']||'').trim(),note:String(values['body-note']||'').trim(),createdAt:old?.createdAt||Date.now(),updatedAt:Date.now()};
  if(!nValidMeasurement(m)||Math.abs(weight*100-Math.round(weight*100))>1e-7||(fat!==null&&Math.abs(fat*10-Math.round(fat*10))>1e-7)||(date===nDate()&&time&&time>new Date().toTimeString().slice(0,5)))return nError('请核对测量日期、时刻、20–300kg体重与体脂率；不能记录未来时间。');
  const ok=await nCommit(next=>{if(id&&!next.measurements.some(x=>x.id===id))return nError('原测量已删除，请重新载入。');if(old&&old.date!==date&&next.representativeByDate[old.date]===id)delete next.representativeByDate[old.date];next.measurements=[...next.measurements.filter(x=>x.id!==m.id),m]});if(ok){nBodyEditing=null;nDismiss();toast('身体测量已保存')}return ok;
}
async function nDeleteBody(id){const ok=await nCommit(next=>{const m=next.measurements.find(x=>x.id===id);if(!m)return false;next.measurements=next.measurements.filter(x=>x.id!==id);if(next.representativeByDate[m.date]===id)delete next.representativeByDate[m.date]});if(ok){nDismiss();toast('测量已删除；历史训练估算保持原值')}return ok}
function nDayReview(date=nutritionDate){const day=nutritionDay(date),body=nutrition.measurements.filter(m=>m.date===date),train=records.filter(r=>r.date===date);nShow('day-review',nHeader('当日回顾 · '+date)+'<h3>身体测量</h3>'+ (body.length?body.map(m=>'<button class="n-row" data-nut-action="body-edit" data-id="'+m.id+'"><span>'+m.weightKg+' kg'+(m.bodyFatPercent===null?'':' · '+m.bodyFatPercent+'%')+'</span><span>'+escapeHTML(m.localTime||'时间未记录')+' ›</span></button>').join(''):'<p class="n-empty">当天未测量</p>')+'<h3>饮食</h3>'+ (day.meals.length?day.meals.map(m=>'<button class="n-row" data-nut-action="meal-detail" data-id="'+m.id+'"><span>'+escapeHTML(m.name)+'</span><span>'+nKcal(nMealCalories(m).unknown?null:nMealCalories(m).known)+' ›</span></button>').join(''):'<p class="n-empty">当天未记饮食</p>')+'<h3>训练</h3><p class="small-label">'+nutritionTrainingSummary(date,date)+'</p>'+ (train.length?train.map(r=>'<button class="n-row" data-nut-action="training-detail" data-id="'+escapeHTML(r.id)+'"><span>'+escapeHTML(recordTitle(r))+'</span><span>'+escapeHTML(recordMetrics(r))+' ›</span></button>').join(''):'<p class="n-empty">当天未保存训练</p>'))}
function nSource(index){const i=mealEditor?.items[index];if(!i)return;const s=i.sourceSnapshot,url=typeof s.url==='string'&&/^https:\/\//.test(s.url)?s.url:null,components=Array.isArray(s.recipe?.components)?s.recipe.components.filter(c=>nObject(c)&&typeof c.name==='string'&&Number.isFinite(c.quantity)&&Number.isFinite(c.energyKcal)):[];nShow('source',nHeader('估算依据','meal-params-return')+'<h3>'+escapeHTML(i.name)+'</h3><p class="subtitle">'+escapeHTML(s.type+' · '+s.name)+'</p><p>'+escapeHTML(i.note)+'</p><p class="subtitle">每'+i.basis.amount+i.unit+'：'+nKcal(i.basis.energyKcal)+'</p>'+(components.length?'<section class="n-recipe-source"><h3>每参考一份的配方</h3>'+components.map(c=>'<div class="n-row"><span>'+escapeHTML(c.name)+'<small>'+escapeHTML(c.quantity+c.unit+' · '+c.note)+'</small></span><span>'+nKcal(c.energyKcal)+'</span></div>').join('')+'<p class="small-label">原料/熟食重量分别按上表口径；修改份数时按比例缩放，不拿成品总重替代原料克重。</p></section>':'')+(s.reference?'<p class="small-label">USDA SR28 NDB '+escapeHTML(s.reference.ndb)+' · '+escapeHTML(s.reference.description)+'</p>':'')+'<p class="small-label">'+escapeHTML(s.license||'用户填写')+'</p><p class="small-label">版本 '+escapeHTML(s.version||'用户填写')+' · 核查 '+escapeHTML(s.checkedAt||'未核实')+'</p>'+(url?'<p class="n-source-url">营养/配方基础来源：'+escapeHTML(url)+'</p><p class="small-label">来源网址供核对，记录与计算离线可用。</p>':'')+(s.menuSource?'<p class="n-source-url">菜名/品牌背景来源（不作为热量来源）：'+escapeHTML(s.menuSource.name)+'<br>'+escapeHTML(s.menuSource.url)+'</p><p class="small-label">'+escapeHTML(s.menuSource.scope)+'</p>':''))}
function nDraftDownload(){const payload={nutrition:nutritionExport(),currentMealDraft:mealEditor,currentBodyForm:nutritionModal==='body-form'?nFormValues(document.getElementById('nutrition-body-form')):null};const url=URL.createObjectURL(new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}));if(window.NextStepAndroid?.exportRecords){window.NextStepAndroid.exportRecords(JSON.stringify(payload,null,2))}else{const a=document.createElement('a');a.href=url;a.download='nextstep-nutrition-backup.json';a.click()}setTimeout(()=>URL.revokeObjectURL(url),1000);toast('已导出饮食、身体与当前草稿')}
async function nRequestClose(){
  if(mealEditor&&['meal-picker','meal-params','combos','source','custom-food','favorite'].includes(nutritionModal)){nReadMealForm();nShow('leave',nHeader('这餐尚未保存')+'<p>保留草稿，下次继续登记；草稿不计入摄入。</p><div class="n-actions"><button class="primary-button" data-nut-action="keep-draft">保留草稿并关闭</button><button class="secondary-button" data-nut-action="meal-params-return">继续填写</button></div><button class="text-button n-full" data-nut-action="discard-draft">放弃这餐草稿</button>'+nBanner());return}
  nDismiss();
}
async function nHandle(action,b){
  const id=b.dataset.id,value=b.dataset.value,index=Number(b.dataset.index);
  switch(action){
    case 'date-prev':nutritionDate=nShift(nutritionDate,-1);nRefresh();break;
    case 'date-next':if(nutritionDate<nDate()){nutritionDate=nShift(nutritionDate,1);nRefresh()}break;
    case 'date-today':nutritionDate=nDate();nRefresh();break;
    case 'meal-new':await nStartMeal(b.dataset.mealType||undefined);break;
    case 'meal-resume':if(nutrition.mealDraft){mealEditor=nClone(nutrition.mealDraft);nMealRender()}break;
    case 'meal-discard-new':if(await nCommit(next=>{next.mealDraft=null})){mealEditor=null;await nStartMeal(b.dataset.mealType)}break;
    case 'picker-tab':mealEditor.picker=value;nMealRender();await nPersistEditor();break;
    case 'food-add':{const f=nFoodList().find(f=>f.id===id);if(f&&mealEditor.items.length<100){mealEditor.items.push(nNewItem(f));await nPersistEditor();document.getElementById('nutrition-selection').textContent='已选 '+mealEditor.items.length+' 项';document.querySelector('[data-nut-action="meal-next"]').disabled=false;toast('已添加 '+f.name)}break}
    case 'recent-add':{const item=nFrequentItems().find(i=>i.foodId===id);if(item){mealEditor.items.push({...nClone(item),id:nId()});mealEditor.step='params';await nPersistEditor();nMealRender()}break}
    case 'meal-next':mealEditor.step='params';await nPersistEditor();nMealRender();break;
    case 'meal-back':nReadMealForm();mealEditor.step='picker';await nPersistEditor();nMealRender();break;
    case 'meal-picker-return':mealEditor.step='picker';nMealRender();break;
    case 'meal-params-return':mealEditor.step=mealEditor.items.length?'params':'picker';nMealRender();break;
    case 'combos':nCombos();break;
    case 'combo-add':{const c=foodCombos.find(c=>c.id===id)||nutrition.favoriteCombos.find(c=>c.id===id);if(c&&mealEditor.items.length+c.items.length<=100){mealEditor.items.push(...nComboItems(c));mealEditor.name=mealEditor.name||c.name;mealEditor.step='params';await nPersistEditor();nMealRender()}break}
    case 'item-remove':nReadMealForm();mealEditor.items.splice(index,1);if(!mealEditor.items.length)mealEditor.step='picker';await nPersistEditor();nMealRender();break;
    case 'portion':{nReadMealForm();const item=mealEditor.items[index],f=foodCatalog.find(f=>f.id===item.foodId);item.quantity=(f?.portion||item.basis.amount)*Number(value);await nPersistEditor();nMealRender();break}
    case 'food-source':nReadMealForm();nSource(index);break;
    case 'custom-food':nCustomFood();break;
    case 'favorite-combo':nReadMealForm();nShow('favorite',nHeader('保存常吃组合','meal-params-return')+'<form id="nutrition-favorite-form">'+nField('favorite-name','组合名称',mealEditor.name,'text','maxlength="60" required')+'<button class="primary-button n-full" type="submit">保存组合</button></form>');break;
    case 'meal-detail':nMealDetail(id);break;
    case 'meal-edit':await nStartMeal(undefined,id);break;
    case 'meal-copy':await nStartMeal(undefined,id,true);break;
    case 'meal-delete-prompt':nShow('delete-meal',nHeader('确认删除这餐')+'<p>删除后需要重新确认当天饮食是否记全。</p><div class="n-actions"><button class="secondary-button" data-nut-action="meal-detail" data-id="'+id+'">保留</button><button class="primary-button" data-nut-action="meal-delete" data-id="'+id+'">确认删除</button></div>');break;
    case 'meal-delete':await nDeleteMeal(id);break;
    case 'meal-skip':if(await nCommit(next=>{nTouchDay(next,nutritionDate);const s=next.dayStates[nutritionDate];s.skipped=s.skipped.includes(b.dataset.mealType)?s.skipped.filter(t=>t!==b.dataset.mealType):[...s.skipped,b.dataset.mealType]}))nRefresh();break;
    case 'confirm-day':await nConfirmDay(nutritionDate);break;
    case 'target':nTargetDialog();break;
    case 'use-body-weight':{const input=document.getElementById(b.dataset.input),m=nutrition.measurements.find(m=>m.id===id),date=input?.id==='sport-weight'?document.getElementById('sport-date')?.value:nDate(new Date(draft?.startedAt||Date.now()));if(input&&m&&m.date<=date){input.value=m.weightKg;input.dispatchEvent(new Event('input',{bubbles:true}));toast('已填入测量体重，请确认适用于记录当时')}else toast('该测量晚于运动日期，请填写记录当时的体重');break}
    case 'body-new':if(nWritable())nBodyForm();break;
    case 'body-edit':nBodyForm(id);break;
    case 'body-metric':bodyMetric=value;nBodyChartRefresh();break;
    case 'body-range':bodyRange=Number(value);nRefresh();document.querySelector('[data-nut-action="body-range"][data-value="'+value+'"]')?.focus?.({preventScroll:true});break;
    case 'body-more':bodyLimit+=20;nRefresh();break;
    case 'body-representative':if(await nCommit(next=>{const m=next.measurements.find(m=>m.id===id);if(!m)return false;next.representativeByDate[m.date]=id})){nRefresh();toast('已设为当天代表值')}break;
    case 'body-sync':{const m=nutrition.measurements.find(m=>m.id===id);if(m){const next={...profile,weight:m.weightKg};if(saveLocal('nextstep.profile',next)){profile=next;toast('资料体重已更新，训练模板保留')}}break}
    case 'body-delete-prompt':nShow('delete-body',nHeader('确认删除测量')+'<p>删除这条测量不会改动历史训练估算。</p><div class="n-actions"><button class="secondary-button" data-nut-action="body-edit" data-id="'+id+'">保留</button><button class="primary-button" data-nut-action="body-delete" data-id="'+id+'">确认删除</button></div>');break;
    case 'body-delete':await nDeleteBody(id);break;
    case 'day-review':nDayReview(b.dataset.date||nutritionDate);break;
    case 'training-detail':nDismiss();recordDialog(id);break;
    case 'close':await nRequestClose();break;
    case 'keep-draft':if(await nPersistEditor()){mealEditor=null;nEditorDirty=false;nDismiss();toast('草稿已保留')}break;
    case 'discard-draft':clearTimeout(nEditorTimer);if(await nCommit(next=>{next.mealDraft=null})){mealEditor=null;nEditorDirty=false;nDismiss();toast('草稿已放弃')}break;
    case 'draft-export':nDraftDownload();break;
    case 'reload':if(mealEditor||nutritionModal==='body-form'){nShow('reload-confirm',nHeader('重新载入数据')+'<p>重新载入会放弃当前窗口尚未保存的输入。可先导出备份。</p><div class="n-actions"><button class="secondary-button" data-nut-action="draft-export">导出当前草稿</button><button class="primary-button" data-nut-action="reload-confirm">已备份，重新载入</button></div>')}else{loadNutrition();nRefresh()}break;
    case 'reload-confirm':clearTimeout(nEditorTimer);mealEditor=null;loadNutrition();nDismiss();break;
  }
}
function nBodyChartRefresh(){const scroll=window.scrollY||0;document.getElementById('body-chart').innerHTML=bodyChart();for(const b of document.querySelectorAll('[data-nut-action="body-metric"]'))b.setAttribute('aria-pressed',String(b.dataset.value===bodyMetric));document.querySelector('[data-nut-action="body-metric"][data-value="'+bodyMetric+'"]')?.focus?.({preventScroll:true});window.scrollTo?.(0,scroll)}
function initializeNutritionUI(){
  document.addEventListener('click',async event=>{const b=event.target.closest('button[data-nut-action]');if(!b||b.disabled)return;const action=b.dataset.nutAction;b.disabled=true;try{await nHandle(action,b)}catch{nError('未能完成操作，填写内容已保留，请重试。')}finally{if(b.isConnected)b.disabled=false}});
  document.addEventListener('input',event=>{const el=event.target;
    if(el.id==='nutrition-search'){mealEditor.query=el.value;document.getElementById('nutrition-picker-results').innerHTML=nPickerResults();nQueueEditor();return}
    if(nutritionModal==='meal-params'&&el.closest('#nutrition-meal-form')){nReadMealForm();document.getElementById('meal-total').textContent=nMealTotalText();document.getElementById('meal-manual-field').hidden=mealEditor.energyMode!=='manual';nQueueEditor();document.getElementById('meal-draft-status').textContent='填写已保留，正在保存草稿…'}
  });
  document.addEventListener('change',event=>{const el=event.target;if(el.id==='nutrition-combo-category'){nutritionComboCategory=el.value;document.getElementById('nutrition-combo-results').innerHTML=nComboResults()}if(el.id==='sport-date')nWeightOptions();if(el.id==='nutrition-date'&&nValidDate(el.value)){nutritionDate=el.value;nRefresh()}if(el.id==='nutrition-category'){mealEditor.category=el.value;document.getElementById('nutrition-picker-results').innerHTML=nPickerResults();nQueueEditor()}if(el.id==='meal-energy-mode'){nReadMealForm();document.getElementById('meal-manual-field').hidden=mealEditor.energyMode!=='manual';document.getElementById('meal-total').textContent=nMealTotalText();nQueueEditor()}if(el.id==='body-date')document.getElementById('body-existing').textContent='当天已有 '+nutrition.measurements.filter(m=>m.date===el.value&&m.id!==nBodyEditing?.id).length+' 条测量；新增不会覆盖已有记录。'});
  document.addEventListener('submit',async event=>{const form=event.target;if(!form.id.startsWith('nutrition-'))return;event.preventDefault();if(!form.reportValidity())return;const submit=form.querySelector('[type="submit"]');if(submit?.disabled)return;if(submit)submit.disabled=true;try{const values=nFormValues(form);if(form.id==='nutrition-meal-form')await nSaveMeal();if(form.id==='nutrition-custom-form')await nAddCustom(values);if(form.id==='nutrition-target-form')await nSaveTarget(values);if(form.id==='nutrition-body-form')await nSaveBody(values);if(form.id==='nutrition-favorite-form'){const name=String(values['favorite-name']||'').trim();if(name&&mealEditor.items.length&&await nCommit(next=>{next.favoriteCombos.push({id:nId(),name,items:nClone(mealEditor.items)});next.mealDraft=nClone(mealEditor)})){mealEditor.step='params';nMealRender();toast('常吃组合已保存')}}}catch{nError('未能保存，填写内容已保留，请重试。')}finally{if(submit?.isConnected)submit.disabled=false}});
  document.getElementById('nutrition-dialog').addEventListener('cancel',event=>{event.preventDefault();nRequestClose()});
  document.getElementById('nutrition-dialog').addEventListener('click',event=>{if(event.target===event.currentTarget){const r=event.currentTarget.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)nRequestClose()}});
  window.addEventListener('storage',event=>{if(event.key===nutritionKey||event.key===null){nutritionConflict=true;const status=document.getElementById('nutrition-error');if(status)status.textContent='其他窗口已更新，输入已保留；请先导出草稿再重新载入。';if(!document.getElementById('nutrition-dialog').open)nRefresh()}});
}
